            o.push_str(&format!(
                "  base {}: winding r = {} (the ROTAT period of {} mod {})\n",
                a, r, a, nv
            ));
            o.push_str(&format!(
                "  a^(r/2) ± 1 splits it: {} = {} × {}   read off the winding, no rho search",
                nv, p, q
            ));
            return o;
        }
    }
    o.push_str(&format!(
        "  no base in the set gave an even winding with a non-trivial split; hand to `trilattice_factor factor {}`",
        n
    ));
    o
}

