/// How many walk steps the order search takes before giving a base up. This is
/// a TIME budget, not a memory one: the rho walk holds a constant handful of
/// residues, no table, so there is nothing to cap for space. The collision
/// arrives in about sqrt(order) steps, so this reach covers orders up to roughly
/// its square. A base that does not collide in budget hands to the next base.
const ORDER_WALK_STEPS: u64 = 400_000_000;

/// A positive multiple of the multiplicative order of `a` modulo `n`, found by
/// Pollard's rho on the exponent, the constant-space read of the ⊡ winding
/// through the ∈/∋ pair. The walk x = a^e takes a pseudo-random stride each
/// step, x -> x·a^{r(x)} with e -> e + r(x); the ∈ fork is the branch on x that
/// picks the stride, the ∋ fuse is Floyd's collision x_i = x_j, and a^{e_i} =
/// a^{e_j} gives a^{|e_i - e_j|} = 1, so |e_i - e_j| is a multiple of the order.
/// This meets by the birthday bound in about sqrt(order) steps holding a handful
/// of residues, no table, so there is no memory ceiling to cap. Returns the
/// multiple, or None if no collision landed within `steps`.
fn order_multiple_rho(a: &BigUint, n: &BigUint, steps: u64) -> Option<BigUint> {
    let one = BigUint::one();
    if a % n == one { return Some(one); }
    // Small pre-walk catches a tiny order directly, where rho's overhead is
    // larger than just multiplying up.
    let mut val = one.clone();
    for k in 1..=64u64 {
        val = (&val * a) % n;
        if val == one { return Some(BigUint::from(k)); }
    }

    // A few restarts, each a different stride table, so a walk that falls into a
    // degenerate zero-length collision tries again rather than failing.
    for seed in 1..=6u64 {
        let stride = |x: &BigUint| -> u64 {
            // pseudo-random small exponent from the residue's low byte
            let low = x.to_u64_digits().first().copied().unwrap_or(0);
            1 + ((low ^ (seed.wrapping_mul(0x9E3779B1))) % 64)
        };
        let step = |x: &BigUint, e: &BigUint| -> (BigUint, BigUint) {
            let r = stride(x);
            let nx = (x * a.modpow(&BigUint::from(r), n)) % n;
            (nx, e + BigUint::from(r))
        };
        let (mut tx, mut te) = (a.clone(), one.clone());       // tortoise, a^1
        let (mut hx, mut he) = (a.clone(), one.clone());       // hare
        let mut moved = 0u64;
        while moved < steps {
            let t = step(&tx, &te); tx = t.0; te = t.1;
            let h1 = step(&hx, &he); let h2 = step(&h1.0, &h1.1); hx = h2.0; he = h2.1;
            moved += 1;
            if tx == hx {
                let d = if te > he { &te - &he } else { &he - &te };
                if d > BigUint::zero() { return Some(d); }
                break; // degenerate collision, restart with the next seed
            }
        }
    }
    None
}

