% VOX / Usurping QM II — unified TikZ visual kit
% Copy the package block + \tikzset block into your paper preamble,
% then copy any figure environment you want.

\documentclass[11pt]{article}
\usepackage[T1]{fontenc}
\usepackage{amsmath,amssymb,mathtools}
\usepackage{graphicx}
\usepackage{tikz}
\usetikzlibrary{arrows.meta,positioning,calc,fit,matrix,decorations.pathreplacing,backgrounds}
\usepackage[margin=1in]{geometry}

% ---------- Shared visual grammar ----------
\tikzset{
  vox/.style={font=\small},
  voxbox/.style={
    draw,
    rounded corners=2pt,
    align=center,
    inner sep=5pt,
    minimum height=9mm
  },
  voxstate/.style={
    draw,
    circle,
    align=center,
    inner sep=1.5pt,
    minimum size=8mm
  },
  voxfaint/.style={draw, densely dashed},
  voxarrow/.style={-{Latex[length=2.2mm]}, line width=.65pt},
  voxback/.style={{Latex[length=2.2mm]}-, line width=.65pt},
  voxdash/.style={-{Latex[length=2.2mm]}, densely dashed, line width=.6pt},
  voxdouble/.style={{Latex[length=2.0mm]}-{Latex[length=2.0mm]}, line width=.6pt},
  voxlabel/.style={font=\scriptsize, fill=white, inner sep=1.5pt},
  voxgroup/.style={draw, rounded corners=3pt, inner sep=6pt, align=center},
  voxslice/.style={draw, rounded corners=2pt, densely dashed, inner sep=4pt, align=center},
  voxmatrix/.style={matrix of math nodes, left delimiter={[}, right delimiter={]},
                   nodes={minimum width=8mm, minimum height=6mm, anchor=center}}
}

% Semantic macro names, so the figures read like the paper.
\newcommand{\voxsplit}{\ensuremath{\in}}
\newcommand{\voxfuse}{\ensuremath{\ni}}
\newcommand{\voxevalt}{\ensuremath{\top}}
\newcommand{\voxevalf}{\ensuremath{\bot}}
\newcommand{\voxengage}{\ensuremath{\boxplus}}
\newcommand{\voxfix}{\ensuremath{\Box}}

\begin{document}

% ============================================================
% FIGURE 1 — The ambient and its classical restrictions
% ============================================================
\begin{figure}[t]
\centering
\begin{tikzpicture}[vox, node distance=12mm and 28mm]
  \node[voxbox, minimum width=48mm] (sixteen)
    {$\mathbf{16}=\mathcal P(\{T,F,t,f\})$\\paraconsistent trilattice};
  \node[voxbox, minimum width=40mm, below=of sixteen] (belnap)
    {$\mathbf 4=\{N,T,F,B\}$\\constructive slice};
  \node[voxbox, minimum width=34mm, below=of belnap] (bool)
    {$\mathbf 2=\{F,T\}$\\Boolean core};

  \draw[voxarrow] (sixteen) -- node[voxlabel,right] {$\rho$} (belnap);
  \draw[voxback, densely dashed] (sixteen) -- node[voxlabel,left] {$\iota_4$} (belnap);

  \draw[voxarrow, bend left=16] (belnap) to node[voxlabel,right] {$r$} (bool);
  \draw[voxarrow, bend right=16] (belnap) to node[voxlabel,left] {$c$} (bool);
  \draw[voxback, densely dashed] (belnap) -- node[voxlabel,left,xshift=-10mm] {$\iota_2$} (bool);

  \node[voxbox, right=32mm of belnap, minimum width=35mm] (loss)
    {$r(N)=r(B)=T$\\$c(N)=c(B)=F$\\[1mm]$B$ has no Boolean name};
  \draw[voxdash] (belnap.east) -- (loss.west);

  \node[below=4mm of bool, align=center, font=\scriptsize]
    {restriction after inclusion is identity;\\restriction alone is non-injective};
\end{tikzpicture}
\caption{The classical description as a lossy restriction of the paraconsistent ambient. The two truth-order adjoints agree on the Boolean core and disagree on the nonclassical values.}
\label{fig:ambient-restriction}
\end{figure}

% ============================================================
% FIGURE 2 — All 16 values as constructive x informational layers
% ============================================================
\begin{figure}[t]
\centering
\begin{tikzpicture}[vox]
  \matrix (M) [matrix of nodes,
    nodes={draw, minimum width=16mm, minimum height=9mm, anchor=center, font=\scriptsize},
    row sep=-\pgflinewidth, column sep=-\pgflinewidth] {
      $N$   & $t$   & $f$   & $tf$   \\
      $T$   & $Tt$  & $Tf$  & $Ttf$  \\
      $F$   & $Ft$  & $Ff$  & $Ftf$  \\
      $B$   & $Bt$  & $Bf$  & $A$    \\
  };

  \node[above=5mm of M-1-2, font=\scriptsize] {informational layer};
  \draw[decorate, decoration={brace, amplitude=4pt}]
    ($(M-1-1.north west)+(0,2mm)$) --
    ($(M-1-4.north east)+(0,2mm)$)
    node[midway, yshift=7mm, font=\scriptsize]
    {$\varnothing,\{t\},\{f\},\{t,f\}$};

  \draw[decorate, decoration={brace, mirror, amplitude=4pt}]
    ($(M-1-1.north west)+(-2mm,0)$) --
    ($(M-4-1.south west)+(-2mm,0)$)
    node[midway, xshift=-14mm, rotate=90, font=\scriptsize]
    {constructive layer $N,T,F,B$};

  \node[voxslice, fit=(M-1-1)(M-4-1), label={[font=\scriptsize]below:Belnap four}] {};
  \node[voxgroup, fit=(M-2-1)(M-3-1), inner sep=2mm,
        label={[font=\scriptsize]left:Boolean core}] {};

  \node[right=12mm of M-2-4, align=left, font=\scriptsize]
    {$16=4\times4$ states\\constructive support $\times$ informational support};
\end{tikzpicture}
\caption{The sixteen-value carrier displayed as the product of constructive and informational support. The Belnap four is the empty-informational column; the Boolean core is the one-sided part of that column.}
\label{fig:sixteen-grid}
\end{figure}

% ============================================================
% FIGURE 3 — Tensor filtration ladder
% ============================================================
\begin{figure}[t]
\centering
\begin{tikzpicture}[vox]
  \foreach \k/\y in {0/0,1/1.25,2/2.5,3/3.75,4/5.0} {
    \node[voxstate] (k\k) at (0,\y) {$|\k\rangle$};
    \draw[voxarrow] (k\k.east) -- ++(29mm,0)
      node[right, font=\scriptsize] {$D|\k\rangle=\k d\,|\k\rangle$};
  }

  \foreach \a/\b/\lab in {
    0/1/{\sqrt{1(m)}},
    1/2/{\sqrt{2(m-1)}},
    2/3/{\sqrt{3(m-2)}},
    3/4/{\sqrt{4(m-3)}}
  } {
    \draw[voxarrow, bend left=20] (k\a) to
      node[voxlabel,right] {$S_+\,\lab$} (k\b);
    \draw[voxarrow, bend left=20] (k\b) to
      node[voxlabel,left] {$S_-\,\lab$} (k\a);
  }

  \node[left=18mm of k2, align=center, font=\scriptsize]
    {\voxsplit\\split / raise};
  \node[right=50mm of k2, align=center, font=\scriptsize]
    {\voxevalt\\evaluate};
  \node[below=6mm of k0, align=center, font=\scriptsize]
    {$S_-=S_+^\dagger$\qquad $[S_+,S_-]|k\rangle=(2k-m)|k\rangle$};
\end{tikzpicture}
\caption{Tensor filtration as a weight-sector ladder. Split raises, fuse lowers, and evaluate reads the occupied sector in place. The same operators generate the spin-$m/2$ angular-momentum algebra.}
\label{fig:filtration-ladder}
\end{figure}

% ============================================================
% FIGURE 4 — Derivation of qubit geometry and Born rule
% ============================================================
\begin{figure}[t]
\centering
\resizebox{\linewidth}{!}{%
\begin{tikzpicture}[vox, node distance=7mm]
  \node[voxbox, minimum width=22mm] (carrier) {$\{T,F\}$\\register};
  \node[voxbox, minimum width=28mm, right=of carrier] (lin)
    {$\ell^2(\{T,F\})$\\linear envelope};
  \node[voxbox, minimum width=26mm, right=of lin] (alg)
    {$S_\pm,K$\\$su(2)$};
  \node[voxbox, minimum width=30mm, right=of alg] (orbit)
    {$SU(2)/U(1)$\\$\cong\mathbb{CP}^{1}\cong S^2$};
  \node[voxbox, minimum width=30mm, right=of orbit] (born)
    {$P_T=|T\rangle\!\langle T|$\\$p_T=\cos^2(\theta/2)$};

  \draw[voxarrow] (carrier) -- node[voxlabel,above] {distinguishability} (lin);
  \draw[voxarrow] (lin) -- node[voxlabel,above] {split/fuse} (alg);
  \draw[voxarrow] (alg) -- node[voxlabel,above] {$m=1$ orbit} (orbit);
  \draw[voxarrow] (orbit) -- node[voxlabel,above] {positive reading} (born);

  \node[below=7mm of alg, font=\scriptsize, align=center]
    {$J_z=K-\tfrac12I$,\quad
      $J_x=\tfrac12(S_++S_-)$,\quad
      $J_y=\tfrac1{2i}(S_+-S_-)$};
\end{tikzpicture}}
\caption{A dependency diagram for the qubit geometry. The projective sphere and the quadratic Born weight arise from the single-coordinate split--fuse representation after canonical linearization, rather than being introduced as an independent ontology.}
\label{fig:born-derivation}
\end{figure}

% ============================================================
% FIGURE 5 — Measurement as filtration, not collapse
% ============================================================
\begin{figure}[t]
\centering
\begin{tikzpicture}[vox, node distance=10mm and 16mm]
  \node[voxbox] (x) {$x$};
  \node[voxbox, right=of x] (split) {$\delta(x)$\\$x\otimes x$};
  \node[voxbox, right=of split, minimum width=31mm] (read)
    {read one factor\\$P_k(x\otimes x)$};
  \node[voxbox, right=of read] (fuse) {$\mu$\\fuse};
  \node[voxbox, right=of fuse] (recover) {$x$\\recovered};

  \draw[voxarrow] (x) -- node[voxlabel,above] {\voxsplit} (split);
  \draw[voxarrow] (split) -- node[voxlabel,above] {filter} (read);
  \draw[voxarrow] (read) -- node[voxlabel,above] {\voxfuse} (fuse);
  \draw[voxarrow] (fuse) -- (recover);

  \node[voxslice, below=17mm of read, minimum width=38mm] (classical)
    {classical record\\keeps one rung};
  \draw[voxdash] (read) -- node[voxlabel,right] {coreflector} (classical);

  \node[voxbox, right=16mm of classical, minimum width=34mm] (loss)
    {unread factors\\not representable};
  \draw[voxarrow] (classical) -- node[voxlabel,above] {discard} (loss);

  \draw[decorate, decoration={brace, mirror, amplitude=4pt}]
    ($(x.south west)+(0,-6mm)$) -- ($(recover.south east)+(0,-6mm)$)
    node[midway, yshift=-9mm, font=\scriptsize]
    {ambient path: reversible filtration};
\end{tikzpicture}
\caption{Measurement as filtration. The ambient path splits, reads, and fuses without deleting the unread factor; the apparent collapse occurs only after projection to the classical record.}
\label{fig:measurement-filtration}
\end{figure}

% ============================================================
% FIGURE 6 — Held relation -> singlet -> cosine -> Tsirelson
% ============================================================
\begin{figure}[t]
\centering
\resizebox{\linewidth}{!}{%
\begin{tikzpicture}[vox, node distance=9mm]
  \node[voxbox] (tf) {$|TF\rangle$};
  \node[voxbox, below=7mm of tf] (ft) {$|FT\rangle$};

  \node[voxbox, right=15mm of tf, yshift=-6mm, minimum width=30mm] (held)
    {shared held relation\\$B_{12}$};
  \node[voxbox, right=of held, minimum width=40mm] (singlet)
    {$|\Omega_B\rangle=\dfrac{|TF\rangle-|FT\rangle}{\sqrt2}$\\$(U\otimes U)|\Omega_B\rangle\sim|\Omega_B\rangle$};
  \node[voxbox, right=of singlet, minimum width=30mm] (corr)
    {$E(\mathbf a,\mathbf b)$\\$=-\mathbf a\!\cdot\!\mathbf b$};
  \node[voxbox, right=of corr, minimum width=26mm] (chsh)
    {$\|\mathcal C\|$\\$\le 2\sqrt2$};

  \draw[voxarrow] (tf) -- (held);
  \draw[voxarrow] (ft) -- (held);
  \draw[voxarrow] (held) -- node[voxlabel,above] {linearize} (singlet);
  \draw[voxarrow] (singlet) -- node[voxlabel,above] {Boolean frames} (corr);
  \draw[voxarrow] (corr) -- node[voxlabel,above] {CHSH} (chsh);

  \node[below=5mm of corr, font=\scriptsize]
    {coplanar: $E(\Delta)=-\cos\Delta$; flip one output convention $\Rightarrow +\cos\Delta$};
\end{tikzpicture}}
\caption{The persistent two-part held relation linearizes to the unique rotation-invariant spin-zero ray. Classical frame readings then produce the cosine correlation and the Tsirelson bound.}
\label{fig:held-correlation}
\end{figure}

% ============================================================
% FIGURE 7 — Token-word -> DQI matrix -> eigenvalue -> scalar
% ============================================================
\begin{figure}[t]
\centering
\resizebox{\linewidth}{!}{%
\begin{tikzpicture}[vox, node distance=10mm]
  \node[voxbox, minimum width=34mm] (word)
    {token-word ladder\\$\voxsplit\;\voxevalt\;\voxfuse$\\$S_+ + D + S_-$};

  \node[voxbox, right=of word, minimum width=50mm] (matrix)
    {$A(m,\ell,d)$\\[-1mm]
    $\begin{bmatrix}
      0 & \sqrt m & & \\
      \sqrt m & d & \sqrt{2(m-1)} & \\
      & \ddots & \ddots & \ddots \\
      & & \sqrt{\ell(m-\ell+1)} & \ell d
    \end{bmatrix}$};

  \node[voxbox, right=of matrix, minimum width=31mm] (eig)
    {finite reading\\$\lambda_{\max}(A)$};

  \node[voxbox, right=of eig, minimum width=30mm] (lim)
    {asymptotic image\\$\lambda_\infty$};

  \draw[voxarrow] (word) -- node[voxlabel,above] {coreflector} (matrix);
  \draw[voxarrow] (matrix) -- node[voxlabel,above] {spectral read} (eig);
  \draw[voxarrow] (eig) -- node[voxlabel,above] {$m\to\infty$} (lim);

  \node[below=6mm of word, font=\scriptsize] {operator-valued original};
  \node[below=6mm of matrix, font=\scriptsize] {finite classical image};
  \node[below=6mm of lim, font=\scriptsize] {scalar coarsening};
\end{tikzpicture}}
\caption{The worked DQI/OPI realization as successive coarsenings of one object: paraconsistent token-word ladder, finite tridiagonal matrix, spectral value, and asymptotic scalar.}
\label{fig:dqi-coarsening}
\end{figure}

% ============================================================
% FIGURE 8 — Tower of gauge ranks
% ============================================================
\begin{figure}[t]
\centering
\begin{tikzpicture}[vox, node distance=12mm and 15mm]
  \node[voxbox] (f1) {$\mathrm{FDE}(1)$\\$2^2=4$ values};
  \node[voxbox, right=of f1] (f2) {$\mathrm{FDE}(2)$\\$2^4=16$ values};
  \node[voxbox, right=of f2] (f3) {$\mathrm{FDE}(3)$\\$2^6=64$ values};
  \node[right=of f3] (dots) {$\cdots$};
  \node[voxbox, right=of dots] (finf) {$\mathrm{FDE}(n)$\\$2^{2n}$ values};

  \draw[voxarrow, bend left=18] (f1) to node[voxlabel,above] {$\iota_1$} (f2);
  \draw[voxarrow, bend left=18] (f2) to node[voxlabel,above] {$\iota_2$} (f3);
  \draw[voxarrow, bend left=18] (f3) to (dots);
  \draw[voxarrow, bend left=18] (dots) to (finf);

  \draw[voxarrow, bend left=18] (f2) to node[voxlabel,below] {$\rho_1$} (f1);
  \draw[voxarrow, bend left=18] (f3) to node[voxlabel,below] {$\rho_2$} (f2);
  \draw[voxarrow, bend left=18] (dots) to (f3);
  \draw[voxarrow, bend left=18] (finf) to (dots);

  \node[below=13mm of f2, align=center, font=\scriptsize]
    {$\rho_n\circ\iota_n=\mathrm{id}$\\$\rho_n$ alone is non-injective};
  \node[below=13mm of f3, align=center, font=\scriptsize]
    {coarse-graining discards exactly\\the new truth/falsity pair};
\end{tikzpicture}
\caption{The rank tower. Each higher carrier embeds the lower one, while restriction deletes the new truth/falsity pair. Restriction after embedding is identity; restriction alone loses information.}
\label{fig:gauge-rank-tower}
\end{figure}

\end{document}

