\documentclass[11pt,a4paper]{article}

\usepackage{fontspec}
\usepackage{amsmath,amsthm,amssymb}
\usepackage{unicode-math}
\setmainfont{Linux Libertine O}
\setmathfont{TeX Gyre Pagella Math}

\usepackage[top=1in, bottom=1in, left=1.15in, right=1.15in, headheight=15pt]{geometry}
\usepackage{microtype}
\usepackage{parskip}
\usepackage[english]{babel}
\setlength{\emergencystretch}{3em}

\usepackage{fancyhdr}
\pagestyle{fancy}
\fancyhf{}
\fancyhead[L]{\leftmark}
\fancyhead[R]{\thepage}
\renewcommand{\headrulewidth}{0.4pt}

\usepackage{titlesec}
\titleformat{\section}{\Large\bfseries}{\thesection}{1em}{}
\titleformat{\subsection}{\large\bfseries}{\thesubsection}{1em}{}

\usepackage{enumitem}
\setlist[itemize]{topsep=0.5ex, itemsep=0.25ex, parsep=0pt}
\setlist[enumerate]{topsep=0.5ex, itemsep=0.4ex, parsep=0pt}

\usepackage{mathtools}
\usepackage{booktabs}
\usepackage{array}
\usepackage{longtable}

\usepackage{hyperref}
\hypersetup{colorlinks=true, linkcolor=blue, urlcolor=cyan, citecolor=blue}

\newcommand{\mvinit}{\vdash}
\newcommand{\mtanch}{\dashv}
\newcommand{\mafwd}{\succ}
\newcommand{\marev}{\prec}
\newcommand{\mclink}{\bowtie}
\newcommand{\mimscrib}{\odot}
\newcommand{\msplit}{\in}
\newcommand{\mfuse}{\ni}
\newcommand{\mevalt}{\top}
\newcommand{\mevalf}{\bot}
\newcommand{\mengagr}{\boxplus}
\newcommand{\mifix}{\boxdot}
\newcommand{\leqi}{\leq_{\mathrm i}}
\newcommand{\leqt}{\leq_{\mathrm t}}
\newcommand{\leqc}{\leq_{\mathrm c}}
\newcommand{\ket}[1]{\lvert #1 \rangle}
\newcommand{\bra}[1]{\langle #1 \rvert}
\providecommand{\llbracket}{\mathopen{\lbrack\!\lbrack}}
\providecommand{\rrbracket}{\mathclose{\rbrack\!\rbrack}}

\newtheorem{theorem}{Theorem}[section]
\newtheorem{proposition}[theorem]{Proposition}
\newtheorem{lemma}[theorem]{Lemma}

