pub fn range(lo: &str, hi: &str, count_only: bool) -> String {
    let lo_t = trim(lo);
    let hi_t = trim(hi);
    if lt(&hi_t, &lo_t) {
        return format!("prime_winding range [{}, {}]: empty span (hi < lo)", lo, hi);
    }
    let mut m = hi_t.clone();
    let mut count: u64 = 0;
    let mut steps: u64 = 0;
    let mut listing = String::new();
    loop {
        if lt(&m, &lo_t) || lt(&m, "2") { break; }
        if let PrimeVerdict::Prime = is_prime(&m) {
            count += 1;
            if !count_only {
                listing.push_str(&m);
                listing.push('\n');
            }
        }
        if m == "2" { break; }
        m = sub(&m, "1");
        steps += 1;
        if steps > RANGE_SCAN_CAP {
            return format!(
                "prime_winding range [{}, {}]: OutOfReach — {} integers scanned, halted at {}, {} prime(s) so far\n{}",
                lo, hi, steps, m, count, listing
            );
        }
    }
    if count_only {
        format!("prime_winding range [{}, {}]: {} prime(s) ({} integers scanned)", lo, hi, count, steps + 1)
    } else {
        format!("prime_winding range [{}, {}]: {} prime(s)\n{}", lo, hi, count, listing)
    }
}

