            let max_n: usize = args.get(1).and_then(|s| s.parse().ok()).unwrap_or(6);
            sprintln!("{}", report(max_n));
        }
        other => sprintln!("multilattice: unknown subcommand '{}' (try 'multilattice help')", other),
    }
}

