pub fn union(self, o: Reg16_3) -> Reg16_3 {
    Reg16_3 {
        big_t: self.big_t || o.big_t, big_f: self.big_f || o.big_f,
        small_t: self.small_t || o.small_t, small_f: self.small_f || o.small_f,
