//! gpu_factor.rs — factoring on the GPU by parallel trial division.
//!
//! The smallest-divisor search is the parallel part: a window of odd candidates
//! is tested at once on the device, each thread checking one divisor of N, the
//! smallest hit taken by an atomic minimum. The host peels factor 2, then walks
//! windows upward; the first window with a hit gives the smallest prime factor,
//! N is divided by it, and the search repeats on the cofactor. A cofactor with
//! no divisor up to its square root is prime.
//!
//! 128-bit, so it covers integers up to about 3.8e38. Trial division finds a
//! factor quickly only when the smallest one is small (the balanced semiprimes
//! `factorgen` makes, factors near 2^31); a number whose least factor is large
//! is Pollard-rho territory and stays on the CPU.

use alloc::format;
use alloc::string::String;
use alloc::vec::Vec;
use cudarc::driver::{CudaContext, CudaStream, CudaFunction, LaunchConfig, PushKernelArg};
use cudarc::nvrtc::{compile_ptx_with_opts, CompileOptions};

pub const GPU_FACTOR_MAX: u128 = 1u128 << 126;

const KERNEL_SRC: &str = r#"
typedef unsigned long long u64;
typedef unsigned __int128 u128;

// Each thread tests one odd divisor d = base + 2*i of N, and the smallest
// divisor found in the window is taken by atomicMin into result.
extern "C" __global__ void smallest_divisor(
    u64 n_lo, u64 n_hi, u64 base, u64 count, unsigned long long* result)
{
    u64 i = (u64)blockIdx.x * blockDim.x + threadIdx.x;
    if (i >= count) return;
    u128 N = ((u128)n_hi << 64) | (u128)n_lo;
    u64 d = base + 2ULL * i;
    u128 dd = (u128)d * (u128)d;
    if (dd > N) return;
    if (N % (u128)d == 0) atomicMin(result, d);
}
"#;

fn isqrt(n: u128) -> u128 {
    if n < 2 { return n; }
    let mut x = n;
    let mut y = (x + 1) / 2;
    while y < x { x = y; y = (x + n / x) / 2; }
    x
}

struct Gpu { stream: alloc::sync::Arc<CudaStream>, func: CudaFunction }

fn setup(device: usize) -> Result<Gpu, String> {
    let ctx = CudaContext::new(device).map_err(|e| format!("gpu_factor: no CUDA context: {e}"))?;
    let stream = ctx.default_stream();
    let opts = CompileOptions { options: alloc::vec!["--device-int128".into()], ..Default::default() };
    let ptx = compile_ptx_with_opts(KERNEL_SRC, opts).map_err(|e| format!("gpu_factor: NVRTC: {e}"))?;
    let module = ctx.load_module(ptx).map_err(|e| format!("gpu_factor: module: {e}"))?;
    let func = module.load_function("smallest_divisor").map_err(|e| format!("gpu_factor: load: {e}"))?;
    Ok(Gpu { stream, func })
}

/// Smallest odd divisor of n in [3, sqrt(n)], or None if n has none (n prime).
fn smallest_odd_divisor(g: &Gpu, n: u128) -> Result<Option<u128>, String> {
    let root = isqrt(n);
    if root < 3 { return Ok(None); }
    const WIN: u64 = 1 << 20;
    let mut base: u64 = 3;
    let root64 = if root > u64::MAX as u128 { u64::MAX } else { root as u64 };
    while base <= root64 {
        // candidates base, base+2, ... up to root64
        let span = (root64 - base) / 2 + 1;
        let count = if span > WIN { WIN } else { span };
        let init: Vec<u64> = alloc::vec![u64::MAX];
        let mut d_res = g.stream.clone_htod(&init).map_err(|e| format!("gpu_factor: htod: {e}"))?;
        let n_lo = (n & 0xFFFF_FFFF_FFFF_FFFF) as u64;
        let n_hi = (n >> 64) as u64;
        let cfg = LaunchConfig::for_num_elems(count as u32);
        let mut b = g.stream.launch_builder(&g.func);
        b.arg(&n_lo); b.arg(&n_hi); b.arg(&base); b.arg(&count); b.arg(&mut d_res);
        unsafe { b.launch(cfg) }.map_err(|e| format!("gpu_factor: launch: {e}"))?;
        let res = g.stream.clone_dtoh(&d_res).map_err(|e| format!("gpu_factor: dtoh: {e}"))?;
        if res[0] != u64::MAX {
            return Ok(Some(res[0] as u128));
        }
        base += 2 * count;
    }
    Ok(None)
}

/// Full prime factorization of n, smallest factor first.
fn factor_full(g: &Gpu, mut n: u128) -> Result<Vec<u128>, String> {
    let mut fs = Vec::new();
