        let mut nl = [rng.n(), rng.n(), rng.n(), rng.n() | (1u64<<63)];
        nl[0] |= 1; // odd
        let bn = from_limbs4(&nl);
        let a = from_limbs4(&[rng.n(), rng.n(), rng.n(), rng.n()]) % &bn;
        let b = from_limbs4(&[rng.n(), rng.n(), rng.n(), rng.n()]) % &bn;
        let r2 = (&two256 * &two256) % &bn;   // R^2 mod N
        for v in limbs4(&a) { a_f.push(v); }
