    let d_n = stream.clone_htod(&n_f).unwrap();
    let d_r2 = stream.clone_htod(&r2_f).unwrap();
    let d_n0 = stream.clone_htod(&n0s).unwrap();
    let mut d_out = stream.alloc_zeros::<u64>(n*4).unwrap();

    let block: u32 = 128;
