            if first.is_empty() { first = format!("  first: got {} expected {}", got, refs[g]); }
        }
    }
    if bad == 0 { format!("gpu_rho verify: {} montgomery products, GPU == BigUint on every one", n) }
    else { format!("gpu_rho verify: {}/{} WRONG\n{}", bad, n, first) }
}

