17	typedef unsigned long long u64;
18	typedef unsigned __int128 u128;
19	
20	// CIOS Montgomery multiply: r = a*b*R^{-1} mod N, R = 2^256. All 4-limb LE.
21	__device__ void montmul(const u64* a, const u64* b, const u64* N, u64 n0, u64* r){
22	    u64 t[6]; for (int i=0;i<6;i++) t[i]=0;
23	    for (int i=0;i<4;i++){
24	        u128 C=0;
25	        for (int j=0;j<4;j++){
26	            u128 x = (u128)a[j]*(u128)b[i] + (u128)t[j] + C;
27	            t[j]=(u64)x; C = x>>64;
28	        }
29	        u128 s = (u128)t[4] + C; t[4]=(u64)s; t[5]=(u64)(s>>64);
30	        u64 m = t[0]*n0;
31	        u128 c2;
32	        { u128 x=(u128)m*(u128)N[0] + (u128)t[0]; c2 = x>>64; }
33	        for (int j=1;j<4;j++){
34	            u128 x=(u128)m*(u128)N[j] + (u128)t[j] + c2;
35	            t[j-1]=(u64)x; c2 = x>>64;
36	        }
37	        u128 s2=(u128)t[4]+c2; t[3]=(u64)s2; c2=s2>>64;
38	        t[4]=t[5]+(u64)c2; t[5]=0;
39	    }
40	    // t[0..4] is the result (up to 5 limbs). Conditional subtract N.
41	    // borrow-compare t (5 limbs, t[4] is 0/1) against N (4 limbs).
42	    bool ge;
43	    if (t[4] != 0) ge = true;
44	    else {
45	        ge = true;
46	        for (int j=3;j>=0;j--){ if (t[j]!=N[j]){ ge = t[j]>N[j]; break; } }
47	    }
48	    if (ge){
49	        u128 br=0;
50	        for (int j=0;j<4;j++){
51	            u128 x = (u128)t[j] - (u128)N[j] - br;
52	            r[j]=(u64)x; br = (x>>64)&1;
53	        }
54	    } else {
55	        for (int j=0;j<4;j++) r[j]=t[j];
56	    }
57	}
58	
59	__device__ bool geq4(const u64* a, const u64* b){
60	    for (int j=3;j>=0;j--){ if (a[j]!=b[j]) return a[j]>b[j]; }
61	    return true;
62	}
63	__device__ void sub4(const u64* a, const u64* b, u64* r){
64	    u128 br=0;
65	    for (int j=0;j<4;j++){ u128 x=(u128)a[j]-(u128)b[j]-br; r[j]=(u64)x; br=(x>>64)&1; }
