83	    for (int j=3;j>0;j--) a[j]=(a[j]<<1)|(a[j-1]>>63);
84	    a[0]<<=1;
85	}
86	// binary gcd of two 256-bit numbers
87	__device__ void gcd4(const u64* aa, const u64* bb, u64* g){
88	    u64 a[4],b[4]; for(int j=0;j<4;j++){a[j]=aa[j];b[j]=bb[j];}
89	    if (is_zero4(a)){ for(int j=0;j<4;j++) g[j]=b[j]; return; }
90	    if (is_zero4(b)){ for(int j=0;j<4;j++) g[j]=a[j]; return; }
91	    int shift=0;
92	    while (((a[0]|b[0])&1)==0){ shr1_4(a); shr1_4(b); shift++; }
93	    while ((a[0]&1)==0) shr1_4(a);
94	    while (!is_zero4(b)){
95	        while ((b[0]&1)==0) shr1_4(b);
96	        // a and b both odd; keep a <= b, then b -= a (b-a is even, >= 0)
97	        if (geq4(a,b)){
98	            u64 t[4]; sub4(a,b,t);              // t = a - b
99	            for (int j=0;j<4;j++) a[j]=b[j];    // a = old b
100	            for (int j=0;j<4;j++) b[j]=t[j];    // b = old a - old b
101	        } else {
102	            u64 t[4]; sub4(b,a,t);
103	            for (int j=0;j<4;j++) b[j]=t[j];    // b = b - a
104	        }
105	    }
106	    for (int s=0;s<shift;s++) shl1_4(a);
107	    for (int j=0;j<4;j++) g[j]=a[j];
108	}
