110	// Pollard rho over Montgomery arithmetic. Each thread walks its own sequence
111	// (distinct c and start), accumulates the product of differences, and takes a
112	// gcd every 128 steps. First thread to find a nontrivial factor writes it.
113	extern "C" __global__ void rho(
114	    const u64* N, const u64* R2, u64 n0, const u64* one_mont,
115	    u64 iters, u64 seed_base,
116	    u64* out_factor, int* found)
