129	        // x = x*x + c
130	        u64 t[4]; montmul(x,x,N,n0,t); montadd(t,c,N,x);
131	        // y = f(f(y))
132	        montmul(y,y,N,n0,t); montadd(t,c,N,y);
133	        montmul(y,y,N,n0,t); montadd(t,c,N,y);
134	        // diff = x - y (mod N)
135	        u64 d[4]; montsub(x,y,N,d);
136	        if (is_zero4(d)) return;   // sequence merged, this walker is done
137	        // q = q * diff
138	        montmul(q,d,N,n0,t); for(int j=0;j<4;j++) q[j]=t[j];
