//! gpu_ecm.rs — Lenstra elliptic-curve factorization on the GPU.
//!
//! One Montgomery curve per thread. Each thread scales its point by
//! k = product of prime powers up to B1 with the x-only Montgomery ladder, over
//! the same verified 256-bit Montgomery field the rho uses, then takes gcd(Z, N).
//! When the curve's order modulo a prime factor p of N is B1-smooth, the ladder
//! drives Z to 0 mod p and the gcd reveals p. Thousands of curves run at once,
//! the first to find a factor writes it. This reaches factors past the rho
//! budget (the 21-digit case), which is what stage-1 ECM is for.

use alloc::format;
use alloc::string::String;
use alloc::vec::Vec;
use cudarc::driver::{CudaContext, LaunchConfig, PushKernelArg};
use cudarc::nvrtc::{compile_ptx_with_opts, CompileOptions};
use num_bigint::BigUint;
use num_traits::{Zero, One};
use crate::gpu_rho::{limbs4, from_limbs4, n0_inv};

const KERNEL_SRC: &str = r#"
typedef unsigned long long u64;
typedef unsigned __int128 u128;

__device__ void montmul(const u64* a, const u64* b, const u64* N, u64 n0, u64* r){
    u64 t[6]; for (int i=0;i<6;i++) t[i]=0;
    for (int i=0;i<4;i++){
        u128 C=0;
        for (int j=0;j<4;j++){ u128 x=(u128)a[j]*(u128)b[i]+(u128)t[j]+C; t[j]=(u64)x; C=x>>64; }
        u128 s=(u128)t[4]+C; t[4]=(u64)s; t[5]=(u64)(s>>64);
        u64 m=t[0]*n0;
        u128 c2; { u128 x=(u128)m*(u128)N[0]+(u128)t[0]; c2=x>>64; }
        for (int j=1;j<4;j++){ u128 x=(u128)m*(u128)N[j]+(u128)t[j]+c2; t[j-1]=(u64)x; c2=x>>64; }
        u128 s2=(u128)t[4]+c2; t[3]=(u64)s2; c2=s2>>64; t[4]=t[5]+(u64)c2; t[5]=0;
    }
    bool ge; if (t[4]!=0) ge=true; else { ge=true; for(int j=3;j>=0;j--){ if(t[j]!=N[j]){ ge=t[j]>N[j]; break; } } }
    if (ge){ u128 br=0; for(int j=0;j<4;j++){ u128 x=(u128)t[j]-(u128)N[j]-br; r[j]=(u64)x; br=(x>>64)&1; } }
    else { for(int j=0;j<4;j++) r[j]=t[j]; }
}
__device__ bool geq4(const u64* a, const u64* b){ for(int j=3;j>=0;j--){ if(a[j]!=b[j]) return a[j]>b[j]; } return true; }
__device__ void sub4(const u64* a, const u64* b, u64* r){ u128 br=0; for(int j=0;j<4;j++){ u128 x=(u128)a[j]-(u128)b[j]-br; r[j]=(u64)x; br=(x>>64)&1; } }
__device__ void montadd(const u64* a, const u64* b, const u64* N, u64* r){
    u128 c=0; u64 t[4]; for(int j=0;j<4;j++){ u128 x=(u128)a[j]+(u128)b[j]+c; t[j]=(u64)x; c=x>>64; }
    if (c!=0 || geq4(t,N)) sub4(t,N,r); else { for(int j=0;j<4;j++) r[j]=t[j]; }
}
__device__ void montsub(const u64* a, const u64* b, const u64* N, u64* r){
    if (geq4(a,b)) sub4(a,b,r); else { u64 t[4]; sub4(b,a,t); sub4(N,t,r); }
}
__device__ bool is_zero4(const u64* a){ return (a[0]|a[1]|a[2]|a[3])==0; }
__device__ void shr1_4(u64* a){ for(int j=0;j<3;j++) a[j]=(a[j]>>1)|(a[j+1]<<63); a[3]>>=1; }
__device__ void shl1_4(u64* a){ for(int j=3;j>0;j--) a[j]=(a[j]<<1)|(a[j-1]>>63); a[0]<<=1; }
__device__ void gcd4(const u64* aa, const u64* bb, u64* g){
    u64 a[4],b[4]; for(int j=0;j<4;j++){a[j]=aa[j];b[j]=bb[j];}
    if (is_zero4(a)){ for(int j=0;j<4;j++) g[j]=b[j]; return; }
    if (is_zero4(b)){ for(int j=0;j<4;j++) g[j]=a[j]; return; }
    int shift=0;
    while (((a[0]|b[0])&1)==0){ shr1_4(a); shr1_4(b); shift++; }
    while ((a[0]&1)==0) shr1_4(a);
    while (!is_zero4(b)){
        while ((b[0]&1)==0) shr1_4(b);
        if (geq4(a,b)){ u64 t[4]; sub4(a,b,t); for(int j=0;j<4;j++) a[j]=b[j]; for(int j=0;j<4;j++) b[j]=t[j]; }
        else { u64 t[4]; sub4(b,a,t); for(int j=0;j<4;j++) b[j]=t[j]; }
    }
    for (int s=0;s<shift;s++) shl1_4(a);
    for (int j=0;j<4;j++) g[j]=a[j];
}

// Montgomery-curve x-only doubling: (X2:Z2) = 2*(X:Z), with a24=(A+2)/4.
__device__ void xDBL(const u64* X, const u64* Z, const u64* a24, const u64* N, u64 n0, u64* OX, u64* OZ){
    u64 t1[4], t2[4], tt[4], tmp[4], x2[4], z2[4];
    montadd(X,Z,N,t1); montmul(t1,t1,N,n0,t1);   // (X+Z)^2
    montsub(X,Z,N,t2); montmul(t2,t2,N,n0,t2);   // (X-Z)^2
    montmul(t1,t2,N,n0,x2);                       // X2
    montsub(t1,t2,N,tt);                          // 4XZ
    montmul(a24,tt,N,n0,tmp); montadd(tmp,t2,N,tmp);
    montmul(tt,tmp,N,n0,z2);                      // Z2
    for(int j=0;j<4;j++){ OX[j]=x2[j]; OZ[j]=z2[j]; }
}
// Differential addition: (X:Z) = (X0:Z0)+(X1:Z1), given diff (Xd:Zd)=P.
__device__ void xADD(const u64* X0,const u64* Z0,const u64* X1,const u64* Z1,
                     const u64* Xd,const u64* Zd,const u64* N,u64 n0,u64* OX,u64* OZ){
    u64 t1[4],t2[4],a[4],b[4],ox[4],oz[4];
    montsub(X0,Z0,N,t1); montadd(X1,Z1,N,t2); montmul(t1,t2,N,n0,a);
    montadd(X0,Z0,N,t1); montsub(X1,Z1,N,t2); montmul(t1,t2,N,n0,b);
    montadd(a,b,N,t1); montmul(t1,t1,N,n0,t1); montmul(Zd,t1,N,n0,ox);
    montsub(a,b,N,t2); montmul(t2,t2,N,n0,t2); montmul(Xd,t2,N,n0,oz);
    for(int j=0;j<4;j++){ OX[j]=ox[j]; OZ[j]=oz[j]; }
}

extern "C" __global__ void ecm(
    const u64* N, const u64* R2, u64 n0,
    const u64* one_mont, const u64* two_mont, const u64* inv4_mont,
    const unsigned char* kbits, int nbits, u64 sigma_base,
    u64* out_factor, int* found)
{
    unsigned int gid = blockIdx.x*blockDim.x + threadIdx.x;
    if (*found != 0) return;
    // curve constant a24 = (A+2)/4, A = to_mont(sigma_base+gid+6)
    u64 A[4], a24[4], t[4];
    u64 sig[4]={sigma_base+gid+6,0,0,0};
    montmul(sig, R2, N, n0, A);
    montadd(A, two_mont, N, t);
    montmul(t, inv4_mont, N, n0, a24);
    // starting point P = (to_mont(sigma_base+gid+2) : 1)
    u64 PX[4], PZ[4];
    u64 xs[4]={sigma_base+gid+2,0,0,0};
    montmul(xs, R2, N, n0, PX);
    for(int j=0;j<4;j++) PZ[j]=one_mont[j];
    // ladder: R0=P, R1=2P
    u64 R0X[4],R0Z[4],R1X[4],R1Z[4];
    for(int j=0;j<4;j++){ R0X[j]=PX[j]; R0Z[j]=PZ[j]; }
    xDBL(PX,PZ,a24,N,n0,R1X,R1Z);
    for (int i=nbits-2; i>=0; i--){
        unsigned char bit = kbits[i];
        if (bit){
            xADD(R0X,R0Z,R1X,R1Z,PX,PZ,N,n0,R0X,R0Z);
            xDBL(R1X,R1Z,a24,N,n0,R1X,R1Z);
        } else {
            xADD(R0X,R0Z,R1X,R1Z,PX,PZ,N,n0,R1X,R1Z);
            xDBL(R0X,R0Z,a24,N,n0,R0X,R0Z);
        }
    }
    u64 g[4]; gcd4(R0Z, N, g);
    bool g1=(g[0]==1&&g[1]==0&&g[2]==0&&g[3]==0);
    bool gN=geq4(g,N)&&geq4(N,g);
    if (!g1 && !gN && !is_zero4(g)){
        if (atomicCAS(found,0,1)==0){ for(int j=0;j<4;j++) out_factor[j]=g[j]; }
    }
}
"#;

/// Primes up to limit (simple sieve).
fn primes_upto(limit: usize) -> Vec<u64> {
    let mut s = alloc::vec![true; limit + 1];
    let mut ps = Vec::new();
    let mut i = 2;
    while i <= limit {
        if s[i] {
            ps.push(i as u64);
            let mut j = i*i;
            while j <= limit { s[j] = false; j += i; }
        }
        i += 1;
    }
    ps
}

/// k = product over primes p<=B1 of p^floor(log B1 / log p).
fn smooth_k(b1: u64) -> BigUint {
    let mut k = BigUint::one();
    for p in primes_upto(b1 as usize) {
        let mut pe = p;
        while pe.saturating_mul(p) <= b1 { pe *= p; }
        k *= BigUint::from(pe);
    }
    k
}

/// One factor of n via GPU ECM stage 1, or None within the curve budget.
pub fn factor_once(n: &BigUint, b1: u64, device: usize) -> Option<BigUint> {
    if n.bits() > 256 || n <= &BigUint::from(3u32) { return None; }
    let nl = limbs4(n);
    if nl[0] & 1 == 0 { return Some(BigUint::from(2u32)); }
    let two256 = BigUint::one() << 256;
    let r2 = (&two256 * &two256) % n;
    let one_mont = (&two256) % n;
    let two_mont = (&two256 * 2u32) % n;
    let inv2 = (n + 1u32) >> 1u32;            // 2^{-1} mod n (n odd)
    let inv4 = (&inv2 * &inv2) % n;           // 4^{-1} mod n
    let inv4_mont = (&inv4 * &two256) % n;
    let n0 = n0_inv(nl[0]);

    let k = smooth_k(b1);
    let nbits = k.bits() as i32;
    let kbits: Vec<u8> = (0..nbits).map(|i| if k.bit(i as u64) {1u8} else {0u8}).collect();

    let ctx = CudaContext::new(device).ok()?;
    let stream = ctx.default_stream();
    let opts = CompileOptions { options: alloc::vec!["--device-int128".into()], ..Default::default() };
    let ptx = compile_ptx_with_opts(KERNEL_SRC, opts).ok()?;
    let module = ctx.load_module(ptx).ok()?;
    let func = module.load_function("ecm").ok()?;

    let d_n = stream.clone_htod(&nl.to_vec()).ok()?;
    let d_r2 = stream.clone_htod(&limbs4(&r2).to_vec()).ok()?;
    let d_om = stream.clone_htod(&limbs4(&one_mont).to_vec()).ok()?;
    let d_tm = stream.clone_htod(&limbs4(&two_mont).to_vec()).ok()?;
    let d_i4 = stream.clone_htod(&limbs4(&inv4_mont).to_vec()).ok()?;
    let d_kb = stream.clone_htod(&kbits).ok()?;

    let threads: u32 = 2048;
    let max_launches = 16u64;
    for l in 0..max_launches {
        let init_found: Vec<i32> = alloc::vec![0];
        let mut d_found = stream.clone_htod(&init_found).ok()?;
        let mut d_out = stream.alloc_zeros::<u64>(4).ok()?;
        let sigma_base = 6 + l * (threads as u64);
        let cfg = LaunchConfig { grid_dim: ((threads+127)/128,1,1), block_dim:(128,1,1), shared_mem_bytes:0 };
        let mut b = stream.launch_builder(&func);
        b.arg(&d_n); b.arg(&d_r2); b.arg(&n0);
        b.arg(&d_om); b.arg(&d_tm); b.arg(&d_i4);
        b.arg(&d_kb); b.arg(&nbits); b.arg(&sigma_base);
        b.arg(&mut d_out); b.arg(&mut d_found);
        if unsafe { b.launch(cfg) }.is_err() { return None; }
        let found = stream.clone_dtoh(&d_found).ok()?;
        if found[0] != 0 {
            let out = stream.clone_dtoh(&d_out).ok()?;
            let f = from_limbs4(&out);
            if f > BigUint::one() && &f < n && (n % &f).is_zero() { return Some(f); }
        }
    }
    None
}

pub fn run_factor(n_str: &str, b1: u64, device: usize) -> String {
    let n: BigUint = match n_str.trim().parse() { Ok(v)=>v, Err(_)=>return format!("gpu_ecm: '{}' not an integer", n_str) };
    match factor_once(&n, b1, device) {
        Some(f) => format!("gpu_ecm factor {} (B1={}): found factor {}  (divides: {})", n, b1, f, (&n % &f).is_zero()),
        None => format!("gpu_ecm factor {} (B1={}): no factor within curve budget", n, b1),
    }
}

