176	fn limbs_of(n: &BigUint, limbs: usize) -> Vec<u64> {
177	    let d = n.to_u64_digits();
178	    let mut v = alloc::vec![0u64; limbs];
179	    for i in 0..limbs { if i < d.len() { v[i] = d[i]; } }
180	    v
181	}
182	fn from_limbs(l: &[u64]) -> BigUint {
183	    let mut n = BigUint::zero();
184	    for i in (0..l.len()).rev() { n = (n << 64) + BigUint::from(l[i]); }
185	    n
186	}
