188	/// Limb count to hold N with a spare limb of headroom.
189	fn pick_limbs(n: &BigUint) -> usize {
190	    let bits = n.bits() as usize;
191	    core::cmp::max(4, bits / 64 + 1)
192	}
193	
194	/// Devices to spread curves across: every CUDA device present.
195	fn devices() -> Vec<usize> {
196	    let mut v = Vec::new();
197	    let mut d = 0usize;
198	    while d < 8 { if CudaContext::new(d).is_ok() { v.push(d); } else { break; } d += 1; }
199	    if v.is_empty() { v.push(0); }
200	    v
201	}
