203	/// ECM stage 1 on one device over its own sigma range, stopping when `stop` is
204	/// set. Returns a factor if this device finds one.
205	fn ecm_worker(n: &BigUint, b1: u64, b2: u64, device: usize, sigma_offset: u64,
206	              stop: &core::sync::atomic::AtomicBool) -> Option<BigUint> {
207	    use core::sync::atomic::Ordering;
208	    let limbs = pick_limbs(n);
209	    let n0 = n0_inv(n.to_u64_digits()[0]);
210	    let r = BigUint::one() << (64 * limbs);
211	    let r2 = (&r * &r) % n;
212	    let one_mont = (&r) % n;
213	    let two_mont = (&r * 2u32) % n;
214	    let inv2 = (n + 1u32) >> 1u32;
215	    let inv4 = (&inv2 * &inv2) % n;
216	    let inv4_mont = (&inv4 * &r) % n;
217	    let k = smooth_k(b1);
218	    let nbits = k.bits() as i32;
219	    let kbits: Vec<u8> = (0..nbits).map(|i| if k.bit(i as u64) {1u8} else {0u8}).collect();
220	
221	    let ctx = CudaContext::new(device).ok()?;
222	    let stream = ctx.default_stream();
223	    let opts = CompileOptions { options: alloc::vec!["--device-int128".into()], ..Default::default() };
224	    let ptx = compile_ptx_with_opts(kernel_src(limbs), opts).ok()?;
225	    let module = ctx.load_module(ptx).ok()?;
226	    let func = module.load_function("ecm").ok()?;
227	
228	    let d_n = stream.clone_htod(&limbs_of(n, limbs)).ok()?;
229	    let d_r2 = stream.clone_htod(&limbs_of(&r2, limbs)).ok()?;
230	    let d_om = stream.clone_htod(&limbs_of(&one_mont, limbs)).ok()?;
231	    let d_tm = stream.clone_htod(&limbs_of(&two_mont, limbs)).ok()?;
232	    let d_i4 = stream.clone_htod(&limbs_of(&inv4_mont, limbs)).ok()?;
233	    let d_kb = stream.clone_htod(&kbits).ok()?;
234	
235	    let threads: u32 = 2048;
236	    let max_launches = 16u64;
237	    for l in 0..max_launches {
238	        if stop.load(Ordering::Relaxed) { return None; }
239	        let init_found: Vec<i32> = alloc::vec![0];
240	        let mut d_found = stream.clone_htod(&init_found).ok()?;
241	        let mut d_out = stream.alloc_zeros::<u64>(limbs).ok()?;
242	        let sigma_base = sigma_offset + 6 + l * (threads as u64);
243	        let cfg = LaunchConfig { grid_dim: ((threads+127)/128,1,1), block_dim:(128,1,1), shared_mem_bytes:0 };
244	        let mut b = stream.launch_builder(&func);
245	        b.arg(&d_n); b.arg(&d_r2); b.arg(&n0);
246	        b.arg(&d_om); b.arg(&d_tm); b.arg(&d_i4);
247	        b.arg(&d_kb); b.arg(&nbits); b.arg(&sigma_base); b.arg(&b1); b.arg(&b2);
248	        b.arg(&mut d_out); b.arg(&mut d_found);
249	        if unsafe { b.launch(cfg) }.is_err() { return None; }
250	        let found = stream.clone_dtoh(&d_found).ok()?;
251	        if found[0] != 0 {
252	            let out = stream.clone_dtoh(&d_out).ok()?;
253	            let f = from_limbs(&out);
254	            if f > BigUint::one() && &f < n && (n % &f).is_zero() {
255	                stop.store(true, Ordering::Relaxed);
256	                return Some(f);
257	            }
258	        }
259	    }
260	    None
261	}
