263	/// One factor of n via GPU ECM stage 1, spread across every device. Curves are
264	/// partitioned by a per-device sigma offset, and the first device to find a
265	/// factor stops the others.
266	pub fn factor_once(n: &BigUint, b1: u64, _device: usize) -> Option<BigUint> {
267	    factor_once_b2(n, b1, b1.saturating_mul(20), _device)
268	}
269	
270	/// ECM with an explicit stage-2 bound b2, spread across every device.
271	pub fn factor_once_b2(n: &BigUint, b1: u64, b2: u64, _device: usize) -> Option<BigUint> {
272	    if n <= &BigUint::from(3u32) { return None; }
273	    let two = BigUint::from(2u32);
274	    if (n % &two).is_zero() { return Some(two); }
275	
276	    let devs = devices();
277	    let stop = std::sync::Arc::new(core::sync::atomic::AtomicBool::new(false));
278	    let result = std::sync::Arc::new(std::sync::Mutex::new(None::<BigUint>));
279	    std::thread::scope(|s| {
280	        for (i, &dev) in devs.iter().enumerate() {
281	            let stop = stop.clone();
282	            let result = result.clone();
283	            let sigma_offset = (i as u64) * 4_000_000_000;
284	            s.spawn(move || {
285	                if let Some(f) = ecm_worker(n, b1, b2, dev, sigma_offset, &stop) {
286	                    *result.lock().unwrap() = Some(f);
287	                }
288	            });
289	        }
290	    });
291	    let g = result.lock().unwrap().clone();
292	    g
293	}
294	
295	fn primes_upto(limit: usize) -> Vec<u64> {
296	    let mut s = alloc::vec![true; limit + 1];
297	    let mut ps = Vec::new();
298	    let mut i = 2;
299	    while i <= limit {
300	        if s[i] { ps.push(i as u64); let mut j=i*i; while j<=limit { s[j]=false; j+=i; } }
301	        i += 1;
302	    }
303	    ps
304	}
305	fn smooth_k(b1: u64) -> BigUint {
306	    let mut k = BigUint::one();
307	    for p in primes_upto(b1 as usize) {
308	        let mut pe = p;
309	        while pe.saturating_mul(p) <= b1 { pe *= p; }
310	        k *= BigUint::from(pe);
311	    }
312	    k
313	}
314	
315	struct Xs(u64);
316	impl Xs { fn n(&mut self)->u64{ let mut x=self.0; x^=x<<13; x^=x>>7; x^=x<<17; self.0=x; x } }
317	
318	/// Verify the width-`limbs` Montgomery multiply against BigUint.
319	pub fn verify_width(limbs: usize, count: usize, seed: u64, device: usize) -> String {
320	    let ctx = match CudaContext::new(device) { Ok(c)=>c, Err(e)=>return format!("gpu_ecm: no ctx: {e}") };
321	    let stream = ctx.default_stream();
322	    let opts = CompileOptions { options: alloc::vec!["--device-int128".into()], ..Default::default() };
323	    let ptx = match compile_ptx_with_opts(kernel_src(limbs), opts) { Ok(p)=>p, Err(e)=>return format!("gpu_ecm: nvrtc: {e}") };
324	    let module = match ctx.load_module(ptx) { Ok(m)=>m, Err(e)=>return format!("gpu_ecm: module: {e}") };
325	    let func = match module.load_function("mont_verify") { Ok(f)=>f, Err(e)=>return format!("gpu_ecm: load: {e}") };
326	    let mut rng = Xs(seed ^ 0xBEEF);
327	    let n = count;
328	    let (mut af,mut bf,mut nf,mut r2f)=(Vec::new(),Vec::new(),Vec::new(),Vec::new());
329	    let mut n0s=Vec::new(); let mut refs=Vec::new();
330	    let r = BigUint::one() << (64*limbs);
331	    for _ in 0..n {
332	        let mut nl: Vec<u64> = (0..limbs).map(|_| rng.n()).collect();
333	        nl[limbs-1] |= 1<<63; nl[0]|=1;
334	        let bn=from_limbs(&nl);
335	        let a=from_limbs(&(0..limbs).map(|_| rng.n()).collect::<Vec<_>>())%&bn;
336	        let b=from_limbs(&(0..limbs).map(|_| rng.n()).collect::<Vec<_>>())%&bn;
337	        let r2=(&r*&r)%&bn;
338	        af.extend(limbs_of(&a,limbs)); bf.extend(limbs_of(&b,limbs)); nf.extend(nl.clone()); r2f.extend(limbs_of(&r2,limbs));
339	        n0s.push(n0_inv(nl[0])); refs.push((&a*&b)%&bn);
340	    }
341	    let d_a=stream.clone_htod(&af).unwrap(); let d_b=stream.clone_htod(&bf).unwrap();
342	    let d_n=stream.clone_htod(&nf).unwrap(); let d_r2=stream.clone_htod(&r2f).unwrap();
343	    let d_n0=stream.clone_htod(&n0s).unwrap(); let mut d_out=stream.alloc_zeros::<u64>(n*limbs).unwrap();
344	    let cc=n as u32;
345	    let cfg=LaunchConfig{grid_dim:((cc+127)/128,1,1),block_dim:(128,1,1),shared_mem_bytes:0};
346	    let mut bd=stream.launch_builder(&func);
347	    bd.arg(&d_a);bd.arg(&d_b);bd.arg(&d_n);bd.arg(&d_r2);bd.arg(&d_n0);bd.arg(&mut d_out);bd.arg(&cc);
348	    if let Err(e)=unsafe{bd.launch(cfg)}{return format!("gpu_ecm: launch: {e}");}
349	    let out=stream.clone_dtoh(&d_out).unwrap();
350	    let mut bad=0; for i in 0..n { if from_limbs(&out[i*limbs..i*limbs+limbs])!=refs[i] { bad+=1; } }
351	    format!("gpu_ecm verify_width {}: {} products, wrong {}", limbs, n, bad)
352	}
353	
354	pub fn run_factor(n_str: &str, b1: u64, device: usize) -> String {
355	    let n: BigUint = match n_str.trim().parse() { Ok(v)=>v, Err(_)=>return format!("gpu_ecm: '{}' not an integer", n_str) };
356	    let b2 = b1.saturating_mul(50);
357	    match factor_once_b2(&n, b1, b2, device) {
358	        Some(f) => format!("gpu_ecm factor {} (B1={}, B2={}): found factor {}  (divides: {})", n, b1, b2, f, (&n % &f).is_zero()),
359	        None => format!("gpu_ecm factor {} (B1={}, B2={}): no factor within curve budget", n, b1, b2),
360	    }
361	}
362

