    let want = args[0];
    match PROBLEMS.iter().find(|(name, _, _)| *name == want) {
        Some((name, note, word)) => report_one(name, note, word),
        None => alloc::format!(
            "no problem named {:?} — run `millennium` with no argument for names\n", want
        ),
    }
}

