276	    let mut progs = alloc::vec![0u8; n * STRIDE];
277	    let mut lens = alloc::vec![0u32; n];
278	    let mut all_ids: Vec<Vec<u8>> = Vec::with_capacity(n);
279	    for g in 0..n {
280	        let len = 4 + (rng.n() % 21) as usize; // 4..24
281	        let mut ids = Vec::with_capacity(len);
282	        for j in 0..len {
283	            let id = marks[(rng.n() % 16) as usize];
284	            progs[g*STRIDE + j] = id;
285	            ids.push(id);
286	        }
287	        lens[g] = len as u32;
288	        all_ids.push(ids);
289	    }
