291	    let d_progs = match stream.clone_htod(&progs) { Ok(d)=>d, Err(e)=>return format!("gpu_kernel: htod progs: {e}") };
292	    let d_lens = match stream.clone_htod(&lens) { Ok(d)=>d, Err(e)=>return format!("gpu_kernel: htod lens: {e}") };
293	    let mut d_stack = match stream.alloc_zeros::<u8>(n * SDEPTH) { Ok(d)=>d, Err(e)=>return format!("gpu_kernel: alloc stack: {e}") };
294	    let mut d_meta = match stream.alloc_zeros::<u32>(n * META) { Ok(d)=>d, Err(e)=>return format!("gpu_kernel: alloc meta: {e}") };
295	
296	    // Each thread carries large local arrays (stack, program, fork stack), so
297	    // keep the block small enough that per-block registers fit.
298	    let block: u32 = 64;
299	    let grid = ((n as u32) + block - 1) / block;
300	    let cfg = LaunchConfig { grid_dim: (grid, 1, 1), block_dim: (block, 1, 1), shared_mem_bytes: 0 };
301	    let mt = max_ticks; let nn = n as u32;
302	    let mut b = stream.launch_builder(&func);
303	    b.arg(&d_progs); b.arg(&d_lens); b.arg(&mut d_stack); b.arg(&mut d_meta); b.arg(&mt); b.arg(&nn);
304	    if let Err(e) = unsafe { b.launch(cfg) } { return format!("gpu_kernel: launch: {e}"); }
305	
306	    let g_stack = match stream.clone_dtoh(&d_stack) { Ok(v)=>v, Err(e)=>return format!("gpu_kernel: dtoh stack: {e}") };
307	    let g_meta = match stream.clone_dtoh(&d_meta) { Ok(v)=>v, Err(e)=>return format!("gpu_kernel: dtoh meta: {e}") };
