309	    let mut mismatches = 0usize;
310	    let mut first = String::new();
311	    for g in 0..n {
312	        let (c_halt, c_tick, c_depth, c_regs, c_engagr, c_mem, c_stack) = cpu_run(&all_ids[g], max_ticks);
313	        let m = &g_meta[g*META..g*META+META];
314	        let g_halt = m[0] as u8; let g_tick = m[1]; let g_top = m[2];
315	        let mut ok = g_halt == c_halt && g_tick == c_tick && g_top == c_depth && (m[11] as u8) == c_engagr;
316	        for i in 0..8 { if m[3+i] as u8 != c_regs[i] { ok = false; } }
