355	pub fn run(word: &str, device: usize) -> String {
356	    use crate::belnap_ring_shor::{Glyph, glyph_to_token};
357	    let mut ids: Vec<u8> = Vec::new();
358	    for (pos, c) in word.chars().filter(|c| !c.is_whitespace()).enumerate() {
359	        match Glyph::from_char(c) {
360	            Some(g) => ids.push(tok_id(glyph_to_token(g))),
361	            None => return format!("gpu_kernel run: char {} ('{}') is not one of the twelve marks", pos, c),
362	        }
363	    }
364	    if ids.is_empty() { return "gpu_kernel run: empty word".into(); }
365	    if ids.len() > STRIDE { return format!("gpu_kernel run: word longer than {} marks", STRIDE); }
