impl WindingState {
    /// Short landing name for the readout.
    pub fn short(self) -> &'static str {
        match self {
            WindingState::A => "A (full top)",
            WindingState::Ftf => "Ftf",
            WindingState::Ttf => "Ttf",
            WindingState::Tf => "tf",
            WindingState::T => "T",
            WindingState::F => "F",
            WindingState::Void => "void",
        }
    }
}

/// The 19-glyph unwinder readout: the canonical word, the twelve phase_1
/// opcode mappings, the per-step walk with its register landing, and the
/// finalize verdict. Descriptive of the ob3ect the module codifies.
pub fn report(canonical_k: u32) -> String {
    use alloc::string::String;
    use alloc::format;
    let mut out = String::new();
    out.push_str("secp256k1 encryption unwinder — 19-glyph morphism sequence\n");
    out.push_str(&format!("word: {}  (period 19, phase-bearing)\n", GLYPH_WORD));
    out.push_str("\nphase_1 opcode → element:\n");
    for (glyph, elem) in PHASE_1_MAPPING.iter() {
        out.push_str(&format!("  {}  {}\n", glyph, elem));
    }
    let rec = WindingRecord::walk(canonical_k);
    out.push_str("\nphase_4 walk (step, glyph, landing, action):\n");
    for step in UnwindStep::ALL.iter() {
        let landing = rec.landings[step.step_index()];
        out.push_str(&format!("  {:>2} {}  {:<12}  {}\n",
            step.step_index() + 1, step.opcode(), landing.short(), step.domain_action()));
    }
    let distinct = {
        let mut seen: Vec<&str> = Vec::new();
        for l in &rec.landings { let s = l.short(); if !seen.contains(&s) { seen.push(s); } }
        seen.len()
    };
    out.push_str(&format!("\ncanonical k: {}\n", canonical_k));
    out.push_str(&format!("distinct landings: {}\n", distinct));
    out.push_str(&format!("verdict: {:?}  (μ∘δ=id closed on clean tri-ancestral rejoin)\n", rec.finalize()));
    out
}

